-- DOCUMENTATION ONLY. PostgreSQL 16. Never execute from this project.
-- ids are generated by the application (no DB defaults).

-- Append-only.
CREATE TABLE audit_log (
  clinic_id     uuid NOT NULL REFERENCES clinics (id),
  id            uuid NOT NULL,
  actor_user_id uuid NOT NULL,
  action        text NOT NULL,
  entity_type   text NOT NULL,
  entity_id     uuid NULL,
  branch_id     uuid NULL,
  details       jsonb NOT NULL,
  created_at    timestamptz NOT NULL,
  PRIMARY KEY (clinic_id, id)
);
CREATE INDEX audit_log_clinic_created_idx ON audit_log (clinic_id, created_at DESC);
CREATE INDEX audit_log_clinic_entity_idx ON audit_log (clinic_id, entity_type, entity_id);

ALTER TABLE audit_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_log FORCE ROW LEVEL SECURITY;
CREATE POLICY audit_log_tenant_isolation ON audit_log
  USING (clinic_id = current_setting('app.clinic_id')::uuid)
  WITH CHECK (clinic_id = current_setting('app.clinic_id')::uuid);
